    print(f'=== Searching {path} for {pattern} ===')
    with pdfplumber.open(path) as pdf:
        for i, p in enumerate(pdf.pages):
            text = p.extract_text() or ''
            if re.search(pattern, text, re.IGNORECASE):
                print(f'--- Page {i+1} ---')
                for line in text.split('\n'):
