import ezdxf, os, math

plan_files = ['E-611_level_1_power_plan.dxf', 'E-612_level_2_power_plan.dxf', 'E-613_roof_power_plan.dxf', 'E-615_site_electrical_plan.dxf', 'E-616_building_4212_power_plan.dxf']
drawings_dir = '/filesystem/electrical__lv_cable_sizing__blind/project/drawings'

horizontal_lengths = {}

for fname in plan_files:
    path = os.path.join(drawings_dir, fname)
    doc = ezdxf.readfile(path)
    msp = doc.modelspace()
    for e in msp:
        layer = e.dxf.layer
        if layer.startswith('E-RTE-'):
            c_id = layer.replace('E-RTE-', '')
            l = 0.0
            if e.dxftype() == 'LINE':
                p1 = e.dxf.start
                p2 = e.dxf.end
                l = math.hypot(p2.x - p1.x, p2.y - p1.y)
            elif e.dxftype() == 'LWPOLYLINE':
                points = e.get_points('xy')
                for i in range(len(points) - 1):
                    l += math.hypot(points[i+1][0] - points[i][0], points[i+1][1] - points[i][1])
            elif e.dxftype() == 'POLYLINE':
                points = [v.dxf.location for v in e.vertices]
                for i in range(len(points) - 1):
                    l += math.hypot(points[i+1].x - points[i].x, points[i+1].y - points[i].y)
            else:
                print('Unknown entity type:', e.dxftype(), layer)
            horizontal_lengths[c_id] = horizontal_lengths.get(c_id, 0.0) + l

for c_id in sorted(horizontal_lengths.keys()):
    print(f'{c_id}: horizontal = {horizontal_lengths[c_id]:.2f} ft')
print('Total circuits found:', len(horizontal_lengths))
